@@ -0,0 +1,42 @@
+// Picks the response language from a request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+/** The best supported language in an Accept-Language header value, or `fallback` when none matches. */
+export function pickLanguage(header, fallback) {
+  if (typeof header !== "string") return fallback;
+  const ranges = [];
+  for (const part of header.split(",")) {
+    const [range, ...params] = part.split(";").map((s) => s.trim().toLowerCase());
+    if (!range) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.*)$/.exec(p);
+      if (!m) continue;
+      if (/^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(m[1])) q = Number(m[1]);
+      else valid = false;
+    }
+    if (!valid) continue;
+    // "ko-KR" counts as "ko"; "*" stands for any language.
+    ranges.push({ lang: range === "*" ? "*" : range.split("-")[0], q });
+  }
+  // The first mention of a language decides its q, so "ko;q=0, ko" stays refused.
+  const refused = new Set();
+  const seen = new Set();
+  for (const r of ranges) {
+    if (seen.has(r.lang)) continue;
+    seen.add(r.lang);
+    if (r.q === 0) refused.add(r.lang);
+  }
+  const wanted = ranges.filter((r, i) => r.q > 0 && ranges.findIndex((o) => o.lang === r.lang) === i);
+  wanted.sort((a, b) => b.q - a.q);
+  for (const { lang } of wanted) {
+    if (LANGUAGES.includes(lang)) return lang;
+    if (lang === "*") {
+      if (!refused.has(fallback)) return fallback;
+      const other = LANGUAGES.find((l) => !refused.has(l));
+      if (other) return other;
+    }
+  }
+  return fallback;
+}
